# Generated by scripts/sync-eval-fixtures.sh from evals/merge-parent-branch/_fixture/fixture.sh + setup.sh. Do not edit.
# Shared fixture for every eval case. scripts/sync-eval-fixtures.sh prepends it to
# each case's setup.sh to build scaffold.sh (scaffolds cannot read files outside their case).
set -euo pipefail

# A dependency-free Node project; the case writes its base files after this.
start_repo() {
  git init -q -b main
  git config user.email eval@example.com
  git config user.name eval
  mkdir -p src test
  cat > package.json << 'JSON'
{ "name": "shop", "private": true, "type": "module", "scripts": { "test": "node --test" } }
JSON
}

# publish_base <subject> <feature>: commits the base on main, cuts develop (the parent) from main and
# the feature branch from develop, so the feature's reflog records develop. All three are pushed to a
# bare origin inside .git/ (which keeps it out of git status). Leaves you on develop.
publish_base() {
  git add -A
  git commit -qm "$1"
  git init -q --bare -b main .git/eval-origin.git
  git remote add origin "$PWD/.git/eval-origin.git"
  git push -q -u origin main
  for branch in develop "$2"; do
    git switch -q -c "$branch"
    git push -q -u origin "$branch"
  done
  git switch -q develop
}

# save <subject>: commits everything on the current branch and pushes it.
save() {
  git add -A
  git commit -qm "$1"
  git push -q
}

# develop adds invoice import and the branch adds CSV export. Each adds an import, a route and a
# menu entry at the same spot, so src/routes.mjs and src/menu.mjs conflict; both features stay,
# each fully wired.
start_repo
cat > src/invoices.mjs << 'JS'
export const listInvoices = () => []
JS
cat > src/routes.mjs << 'JS'
import { listInvoices } from "./invoices.mjs"

export const routes = {
  "GET /invoices": listInvoices,
}
JS
cat > src/menu.mjs << 'JS'
export const menu = [
  { label: "Invoices", path: "/invoices" },
]
JS
publish_base "Add invoice routes and menu" feature/invoice-export

cat > src/import.mjs << 'JS'
// Parses an uploaded CSV body into invoices.
export const importInvoices = (body) => body.trim().split("\n").slice(1).map((line) => ({ id: line.split(",")[0] }))
JS
cat > src/routes.mjs << 'JS'
import { listInvoices } from "./invoices.mjs"
import { importInvoices } from "./import.mjs"

export const routes = {
  "GET /invoices": listInvoices,
  "POST /invoices/import": importInvoices,
}
JS
cat > src/menu.mjs << 'JS'
export const menu = [
  { label: "Invoices", path: "/invoices" },
  { label: "Import", path: "/invoices/import" },
]
JS
save "Add invoice import"

git switch -q feature/invoice-export
cat > src/export.mjs << 'JS'
// Serializes invoices as CSV, one row per invoice.
export const exportCsv = (invoices) => ["id", ...invoices.map((invoice) => invoice.id)].join("\n")
JS
cat > src/routes.mjs << 'JS'
